-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "itIT" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.mop.monk.brewmaster.Name"] = "Consigliata"
L["rm.mop.monk.brewmaster.Description"] = "Scelta automaticamente nella specializzazione Mastro Birraio. Mantiene attivo Passo Barcollante con Calcio dell'Oscuramento, usa Lancio del Barile ogni volta che il suo Chi non va sprecato, Espulsione del Dolore quando sei ferito (subito sotto il 35%), Diretto per spendere energia, Palmo della Tigre per Potere della Tigre e come riempitivo gratuito (Diretto accumula Chi prima del livello 34), e Tocco della Morte quando è utilizzabile. Dalla distanza fuori dal combattimento: Ondata del Chi, Ebbrezza, Scontro o Lancio del Barile. Contro tre o più nemici: Tornado di Giada, Soffio di Fuoco e Calcio Rotante della Gru solo mentre Passo Barcollante ha tempo residuo. Promemoria: Stile dello Yak Robusto, Eredità dell'Imperatore, Birra Purificatrice con Noncuranza Totale (Moderata quando Passo Barcollante è in riserva), Birra Elusiva da sei cumuli, Guardia con Guardia Potenziata, Birra del Chi, Xuen, Birra Fortificante, Diminuzione del Dolore o Dispersione della Magia quando sei in difficoltà, Compressione Tracheale. Il promemoria della Statua dello Yak Nero è disattivato; Allontanamento dal Male, Meditazione Zen e Istigazione restano a te."
L["rm.mop.monk.brewmaster.offensive.Name"] = "Prima i danni (simulatore)"
L["rm.mop.monk.brewmaster.offensive.Description"] = "Un'alternativa alla rotazione integrata Mastro Birraio, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alzane la priorità. Segue la lista del simulatore che dà priorità ai danni, per un difensore con equipaggiamento superiore al contenuto: Tornado di Giada prima di Lancio del Barile, Chi speso in Calcio dell'Oscuramento per i danni, e niente Birra Purificatrice o Guardia di routine (Birra Purificatrice si accende solo con il proc Purificatore del set del Tier 15). Birra Elusiva, Birra del Chi, Xuen e Birra Fortificante restano promemoria."
L["rm.mop.monk.mistweaver.Name"] = "Consigliata"
L["rm.mop.monk.mistweaver.Description"] = "Scelta automaticamente nella specializzazione Mistweaver. Con un bersaglio amico cura quel bersaglio: Nebbia Curativa appena pronta, Alleviamento quando tre o più alleati vicini sono feriti, Espulsione del Dolore e il tuo talento del Chi per il Chi, Tornado di Giada o Calcio Rotante della Gru per un gruppo ferito, Nebbia Crescente a cinque Nebbie Vitali, Nebbia del Sollievo quando il bersaglio è sotto l'80%, poi Nebbia Avvolgente e Nebbia Crescente durante quella canalizzazione. Con un bersaglio nemico fa fistweaving: Palmo della Tigre e Calcio dell'Oscuramento con Memoria Muscolare per mantenere Potere della Tigre e Zelo della Serpe, Calcio dell'Oscuramento quando il Chi è pieno, Nebbia Crescente a cinque Nebbie Vitali, Nebbia Curativa ed Espulsione del Dolore per il Chi, Diretto. Promemoria: Stile della Serpe Saggia, Eredità dell'Imperatore, la Statua della Serpe di Giada in gruppo, Tè al Mana nei momenti tranquilli, Tè della Concentrazione del Tuono, Birra del Chi, Bozzolo di Vita su un alleato sotto il 35%, Xuen, Disintossicazione, abilità difensive, Compressione Tracheale. Scegli tu chi curare; Palingenesi (promemoria disattivato) e Sfera Curativa restano a te."
L["rm.mop.monk.unspecialized.Name"] = "Prima di una specializzazione"
L["rm.mop.monk.unspecialized.Description"] = "Per i livelli da 1 a 9, o per qualsiasi monaco che non ha scelto una specializzazione; una rotazione integrata di specializzazione subentra appena ne scegli una. Mantiene attivi Stile della Tigre e Potere della Tigre, spende due Chi in Calcio dell'Oscuramento, usa Espulsione del Dolore quando sei ferito e altrimenti Diretto."
L["rm.mop.monk.windwalker.Name"] = "Consigliata"
L["rm.mop.monk.windwalker.Description"] = "Scelta automaticamente nella specializzazione Impeto. Tocco della Morte quando è utilizzabile, Palmo della Tigre per mantenere Potere della Tigre, Calcio del Sole Nascente appena pronto, Ondata del Chi, proc di Combo Magistrale, Pugni della Furia quando stai fermo e la sua canalizzazione non porta la tua energia al massimo, Diretto quando mancano due Chi (invece Espulsione del Dolore quando sei ferito), Calcio dell'Oscuramento senza lasciare a secco il successivo Calcio del Sole Nascente. Contro due o più nemici Calcio del Sole Nascente mantiene attiva la sua penalità e da tre si aggiunge Calcio Rotante della Gru o Tornado di Giada. Promemoria: Stile della Tigre, Eredità dell'Imperatore e della Tigre Bianca, Birra dell'Occhio di Tigre a 19 cumuli (15 con Chi da spendere, 10 durante Brama di Sangue o verso la fine di un combattimento), Birra Rinvigorente con poca energia, Birra del Chi, Xuen, Tempesta, Terra e Fuoco contro due nemici (lo lanci sul secondo), Tocco del Karma, abilità difensive e Compressione Tracheale. I controlli sull'energia al massimo sono soglie di energia, quindi regolale in base alla tua celerità."
L["rm.mop.monk.windwalker.simc.Name"] = "SimulationCraft 5.4.8 (Hekili e MaxDps)"
L["rm.mop.monk.windwalker.simc.Description"] = "Un'alternativa alla rotazione integrata Impeto, disattivata per impostazione predefinita: attivala e disattiva l'altra, oppure alzane la priorità. La lista originale di SimulationCraft distribuita con gli addon Hekili e MaxDps: Potere della Tigre rinnovato a tre secondi, Calcio del Sole Nascente per primo mentre manca la sua penalità, Pugni della Furia conservato per Birra dell'Occhio di Tigre (attiva o a 15 cumuli), Birra dell'Occhio di Tigre a 20 cumuli o a 15 con Chi ed entrambi gli effetti benefici attivi. Contro tre o più nemici spende su Calcio Rotante della Gru, usa Calcio del Sole Nascente solo con il Chi pieno e accumula energia sotto 60."
L["rm.retail.monk.brewmaster.Name"] = "Assistente di Combattimento di Blizzard con birre"
L["rm.retail.monk.brewmaster.Description"] = "Consigliata per Mastro Birraio. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. L'Assistente di Combattimento non usa le birre, quindi, come consiglia Icy Veins, le birre sono promemoria al suo fianco: Birra dello Yak Nero, Invocazione: Niuzao, lo Yak Nero, Birra Purificatrice, Birra Celestiale o Infusione Celestiale e Tocco della Morte si illuminano appena sono pronti in combattimento (Rotation Master non può ancora leggere Noncuranza, quindi valutare quanto sia pesante resta a te). Inoltre Compressione Tracheale su un lancio interrompibile, e Birra Fortificante e il tuo tempo di recupero razziale ogni volta che sono pronti in combattimento; i lanci nemici sono nascosti in combattimento, quindi l'interruzione si illumina solo dove il gioco li mostra, e la salute è nascosta su Retail, quindi decidi tu quando usare Birra Fortificante."
L["rm.retail.monk.brewmaster.guide.Name"] = "Riferimento (Icy Veins)"
L["rm.retail.monk.brewmaster.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità Mastro Birraio di Icy Veins (SimulationCraft concorda nella sostanza). Combo dell'Oscuramento, Barile Vuoto e le cariche sono nascosti in combattimento in Midnight, quindi lì non può funzionare. Ingaggia con Lancio del Barile. Calcio dell'Oscuramento; Scarica del Chi (Maestro dell'Armonia); Palmo della Tigre con Combo dell'Oscuramento; Lancio del Barile a cariche piene o con Barile Vuoto; Soffio di Fuoco; Tornado di Giada prima di Barile d'Esplosivo; Scarica del Chi (Shandaren); Lancio del Barile; Tornado di Giada e Calcio Rotante della Gru contro tre o più nemici; Palmo della Tigre; Espulsione del Dolore. Promemoria: Birra dello Yak Nero dopo aver usato Birra Purificatrice e Birra Celestiale, Invocazione: Niuzao, lo Yak Nero, Birra Purificatrice, Birra Celestiale o Infusione Celestiale, Tocco della Morte, più i promemoria di utilità."
L["rm.retail.monk.initial.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.monk.initial.Description"] = "Consigliata prima di scegliere una specializzazione (mentre il gioco segnala la specializzazione iniziale del Monaco). Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight; attende mentre lanci o incanali. Al suo fianco, i promemoria che ogni rotazione integrata del Monaco condivide, ciascuno una volta che conosci il suo incantesimo. Quando scegli una specializzazione al livello 10, subentrano le rotazioni integrate di quella specializzazione."
L["rm.retail.monk.mistweaver.Name"] = "Riferimento (Icy Veins)"
L["rm.retail.monk.mistweaver.Description"] = "Solo riferimento, disattivata per impostazione predefinita. Blizzard non offre una lista dell'Assistente di Combattimento per i guaritori, e in combattimento in Midnight la salute dei tuoi alleati, le cariche di Nebbia Curativa, i cumuli di Tè al Mana e i proc sono nascosti agli addon, quindi i consigli di cura non sono possibili; scegli tu le tue cure. Su un bersaglio ostile suggerisce il riempitivo del fistweaving (cure tramite attacchi in mischia), Calcio del Sole Nascente, Calcio dell'Oscuramento e Palmo della Tigre; su un bersaglio amico o senza bersaglio non suggerisce nulla. Promemoria: Compressione Tracheale, e Birra Fortificante e il tuo tempo di recupero razziale ogni volta che sono pronti in combattimento."
L["rm.retail.monk.windwalker.Name"] = "Assistente di Combattimento di Blizzard"
L["rm.retail.monk.windwalker.Description"] = "Consigliata per Impeto. Evidenzia il prossimo incantesimo suggerito dall'Assistente di Combattimento di Blizzard, l'unico consiglio di rotazione che il gioco permette ancora a un addon di leggere in combattimento in Midnight (rispetta già Sequenza Combo); attende mentre lanci o incanali. Al suo fianco, promemoria per ciò che l'Assistente di Combattimento lascia a te: Zenith, Condotto Celestiale, Invocazione: Xuen, la Tigre Bianca e Tocco del Karma in combattimento, Compressione Tracheale su un lancio interrompibile, e Birra Fortificante e il tuo tempo di recupero razziale ogni volta che sono pronti in combattimento. I lanci nemici sono nascosti in combattimento, quindi l'interruzione si illumina solo dove il gioco li mostra; la salute è nascosta su Retail, quindi decidi tu quando usare Birra Fortificante."
L["rm.retail.monk.windwalker.guide.Name"] = "Riferimento (Icy Veins e SimulationCraft)"
L["rm.retail.monk.windwalker.guide.Description"] = "Solo riferimento, disattivata per impostazione predefinita: la priorità Condotto dei Celestiali di Icy Veins. Ogni passaggio rispetta Sequenza Combo (mai l'ultimo incantesimo lanciato); il Chi e i tuoi lanci restano leggibili, ma Cuore della Serpe di Giada, Zenith, Calcio dell'Oscuramento! e Danza di Chi-Ji sono nascosti in combattimento in Midnight, quindi lì non può funzionare; l'energia è nascosta su Retail, quindi il Palmo della Tigre prima del massimo di energia è escluso. Pugno Rotante del Drago quando mancano più di 10 secondi a Xuen; Urto dello Zenith con poco Chi o quando Zenith sta finendo; Condotto Celestiale senza Cuore; Pugni della Furia quando Cuore sta finendo; Condotto Celestiale, Invocazione: Xuen, la Tigre Bianca, Pugni della Furia, Pugno Rotante del Drago, Assalto del Signore del Vento; Calcio dell'Oscuramento quando manca il Chi per Pugni; Calcio dei Venti Impetuosi, Calcio del Sole Nascente; Calcio dell'Oscuramento con due cariche di Calcio dell'Oscuramento! o durante Zenith; Calcio Rotante della Gru durante Zenith o con Danza di Chi-Ji; Tocco della Morte; Palmo della Tigre, Calcio dell'Oscuramento, Venti Taglienti come riempitivi. Promemoria: Tocco del Karma, più i promemoria di utilità."
